CREATE TABLE public.visitor_workspace_grants (user_id uuid PRIMARY KEY, enabled boolean NOT NULL DEFAULT false, enabled_by uuid, note text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.visitor_workspace_grants TO authenticated; GRANT ALL ON public.visitor_workspace_grants TO service_role;
ALTER TABLE public.visitor_workspace_grants ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.visitor_sites (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, name text NOT NULL DEFAULT 'Website', allowed_domains text[] NOT NULL DEFAULT '{}', verified_hosts text[] NOT NULL DEFAULT '{}', consent_mode text NOT NULL DEFAULT 'required' CHECK(consent_mode IN ('required','not_required')), excluded_paths text[] NOT NULL DEFAULT '{}', excluded_ips text[] NOT NULL DEFAULT '{}', retention_days integer NOT NULL DEFAULT 90 CHECK(retention_days BETWEEN 7 AND 365), enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,user_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.visitor_sites TO authenticated; GRANT ALL ON public.visitor_sites TO service_role; ALTER TABLE public.visitor_sites ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.visitor_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),site_id uuid NOT NULL REFERENCES public.visitor_sites(id) ON DELETE CASCADE,user_id uuid NOT NULL,event_id text NOT NULL,event_name text NOT NULL,path text NOT NULL DEFAULT '/',page_type text NOT NULL DEFAULT 'other',referrer_host text,utm jsonb NOT NULL DEFAULT '{}',props jsonb NOT NULL DEFAULT '{}',session_id text NOT NULL,visitor_key text NOT NULL,is_returning boolean NOT NULL DEFAULT false,engagement jsonb,is_test boolean NOT NULL DEFAULT false,received_at timestamptz NOT NULL DEFAULT now(),UNIQUE(site_id,event_id));
GRANT SELECT ON public.visitor_events TO authenticated; GRANT ALL ON public.visitor_events TO service_role; ALTER TABLE public.visitor_events ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.visitor_company_matches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),site_id uuid NOT NULL REFERENCES public.visitor_sites(id) ON DELETE CASCADE,user_id uuid NOT NULL,visitor_key text NOT NULL,company_id uuid,person_id uuid,lead_id uuid,status text NOT NULL CHECK(status IN ('matched','unknown')),classification text NOT NULL DEFAULT 'unknown',company_name text,company_domain text,confidence numeric(3,2),unknown_reason text,evidence jsonb NOT NULL DEFAULT '[]',network_prefix text,first_seen timestamptz NOT NULL DEFAULT now(),last_seen timestamptz NOT NULL DEFAULT now(),resolved_at timestamptz,UNIQUE(site_id,visitor_key),CONSTRAINT visitor_matches_confidence_when_known CHECK((status='matched' AND confidence IS NOT NULL AND company_name IS NOT NULL AND company_domain IS NOT NULL) OR(status='unknown' AND confidence IS NULL AND company_name IS NULL)));
GRANT SELECT ON public.visitor_company_matches TO authenticated; GRANT ALL ON public.visitor_company_matches TO service_role; ALTER TABLE public.visitor_company_matches ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.visitor_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),site_id uuid NOT NULL REFERENCES public.visitor_sites(id) ON DELETE CASCADE,user_id uuid NOT NULL,name text NOT NULL,enabled boolean NOT NULL DEFAULT false,page_types text[] NOT NULL DEFAULT '{}',event_names text[] NOT NULL DEFAULT '{page_view}',min_confidence numeric(3,2) NOT NULL DEFAULT 0.70,actions text[] NOT NULL DEFAULT '{find_contacts,enrich,draft}',sequence_id uuid,daily_cap integer NOT NULL DEFAULT 5 CHECK(daily_cap BETWEEN 1 AND 25),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT visitor_rules_site_user_fkey FOREIGN KEY(site_id,user_id) REFERENCES public.visitor_sites(id,user_id) ON DELETE CASCADE);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.visitor_rules TO authenticated; GRANT ALL ON public.visitor_rules TO service_role; ALTER TABLE public.visitor_rules ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.visitor_rule_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),rule_id uuid NOT NULL REFERENCES public.visitor_rules(id) ON DELETE CASCADE,match_id uuid NOT NULL REFERENCES public.visitor_company_matches(id) ON DELETE CASCADE,user_id uuid NOT NULL,status text NOT NULL CHECK(status IN ('running','completed','failed','skipped')),skip_reason text,actions_taken jsonb NOT NULL DEFAULT '[]',created_at timestamptz NOT NULL DEFAULT now(),finished_at timestamptz,UNIQUE(rule_id,match_id));
GRANT SELECT ON public.visitor_rule_runs TO authenticated; GRANT ALL ON public.visitor_rule_runs TO service_role; ALTER TABLE public.visitor_rule_runs ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.visitor_resolve_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),site_id uuid NOT NULL REFERENCES public.visitor_sites(id) ON DELETE CASCADE,user_id uuid NOT NULL,visitor_key text NOT NULL,ip_hash text NOT NULL,ip_raw text,ip_raw_until timestamptz,network_prefix text,status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','running','done','failed')),attempts integer NOT NULL DEFAULT 0,last_error text,available_at timestamptz NOT NULL DEFAULT now(),claimed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),finished_at timestamptz,UNIQUE(site_id,ip_hash));
GRANT ALL ON public.visitor_resolve_jobs TO service_role; REVOKE ALL ON public.visitor_resolve_jobs FROM PUBLIC,anon,authenticated; ALTER TABLE public.visitor_resolve_jobs ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.visitor_network_cache (network_prefix text PRIMARY KEY,classification text NOT NULL,unknown_reason text,evidence jsonb NOT NULL DEFAULT '[]',fetched_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL);
GRANT ALL ON public.visitor_network_cache TO service_role; REVOKE ALL ON public.visitor_network_cache FROM PUBLIC,anon,authenticated; ALTER TABLE public.visitor_network_cache ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.visitor_ip_cache (ip_hash text PRIMARY KEY,status text NOT NULL CHECK(status IN ('matched','unknown')),classification text NOT NULL,company_name text,company_domain text,confidence numeric(3,2),unknown_reason text,evidence jsonb NOT NULL DEFAULT '[]',network_prefix text,fetched_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL);
GRANT ALL ON public.visitor_ip_cache TO service_role; REVOKE ALL ON public.visitor_ip_cache FROM PUBLIC,anon,authenticated; ALTER TABLE public.visitor_ip_cache ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.visitor_workspace_owner() RETURNS uuid LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE owner uuid; BEGIN IF auth.uid() IS NULL THEN RETURN NULL; END IF; SELECT team_owner_id INTO owner FROM public.team_members WHERE member_user_id=auth.uid() AND status='active' ORDER BY created_at LIMIT 1; RETURN coalesce(owner,auth.uid()); END; $$;
CREATE OR REPLACE FUNCTION public.visitor_intelligence_enabled() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.visitor_workspace_owner() IS NOT NULL AND EXISTS(SELECT 1 FROM public.feature_flags WHERE name='visitorIntelligence' AND is_enabled IS TRUE) AND EXISTS(SELECT 1 FROM public.visitor_workspace_grants WHERE user_id=public.visitor_workspace_owner() AND enabled IS TRUE); $$;
REVOKE ALL ON FUNCTION public.visitor_workspace_owner(),public.visitor_intelligence_enabled() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.visitor_workspace_owner(),public.visitor_intelligence_enabled() TO authenticated,service_role;
CREATE POLICY visitor_grants_select ON public.visitor_workspace_grants FOR SELECT TO authenticated USING(user_id=public.visitor_workspace_owner());
CREATE POLICY visitor_grants_admin ON public.visitor_workspace_grants FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE POLICY visitor_sites_rw ON public.visitor_sites FOR ALL TO authenticated USING(user_id=public.visitor_workspace_owner() AND public.visitor_intelligence_enabled()) WITH CHECK(user_id=public.visitor_workspace_owner() AND public.visitor_intelligence_enabled());
CREATE POLICY visitor_rules_rw ON public.visitor_rules FOR ALL TO authenticated USING(user_id=public.visitor_workspace_owner() AND public.visitor_intelligence_enabled()) WITH CHECK(user_id=public.visitor_workspace_owner() AND public.visitor_intelligence_enabled());
CREATE POLICY visitor_events_select ON public.visitor_events FOR SELECT TO authenticated USING(user_id=public.visitor_workspace_owner() AND public.visitor_intelligence_enabled());
CREATE POLICY visitor_matches_select ON public.visitor_company_matches FOR SELECT TO authenticated USING(user_id=public.visitor_workspace_owner() AND public.visitor_intelligence_enabled());
CREATE POLICY visitor_runs_select ON public.visitor_rule_runs FOR SELECT TO authenticated USING(user_id=public.visitor_workspace_owner() AND public.visitor_intelligence_enabled());
CREATE OR REPLACE FUNCTION public.visitor_touch_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END; $$;
CREATE TRIGGER visitor_sites_touch BEFORE UPDATE ON public.visitor_sites FOR EACH ROW EXECUTE FUNCTION public.visitor_touch_updated_at(); CREATE TRIGGER visitor_rules_touch BEFORE UPDATE ON public.visitor_rules FOR EACH ROW EXECUTE FUNCTION public.visitor_touch_updated_at(); CREATE TRIGGER visitor_grants_touch BEFORE UPDATE ON public.visitor_workspace_grants FOR EACH ROW EXECUTE FUNCTION public.visitor_touch_updated_at();
CREATE INDEX idx_visitor_sites_user ON public.visitor_sites(user_id,created_at DESC); CREATE INDEX idx_visitor_events_site_time ON public.visitor_events(site_id,received_at DESC); CREATE INDEX idx_visitor_events_visitor ON public.visitor_events(site_id,visitor_key,received_at DESC); CREATE INDEX idx_visitor_matches_user ON public.visitor_company_matches(user_id,last_seen DESC); CREATE INDEX idx_visitor_rules_site ON public.visitor_rules(site_id,enabled); CREATE INDEX idx_visitor_rule_runs_day ON public.visitor_rule_runs(user_id,created_at DESC); CREATE INDEX idx_visitor_jobs_claim ON public.visitor_resolve_jobs(status,available_at);
DO $health$ DECLARE definition text:=pg_get_functiondef('public._system_health_checks()'::regprocedure); old text:='c.relname IN (''stripe_credit_grants'', ''outbound_gate_canary'')'; BEGIN IF position(old IN definition)=0 THEN RAISE EXCEPTION 'Health predicate changed'; END IF; EXECUTE replace(definition,old,'c.relname IN (''stripe_credit_grants'', ''outbound_gate_canary'', ''visitor_resolve_jobs'', ''visitor_network_cache'', ''visitor_ip_cache'')'); END; $health$;
DO $regression$ DECLARE report jsonb:=public._system_health_checks(); BEGIN IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(report->'checks') c WHERE c->>'id'='api_grants' AND c->>'status'='pass') THEN RAISE EXCEPTION 'Regression: private visitor jobs trigger false outage'; END IF; END; $regression$;